import { randomUUID } from 'crypto';
import { createLogger } from '../utils/logger';
import { SUPPORT_TICKET_WEBHOOK_URL } from '../config/proxy';

const log = createLogger('SupportTicketService');

export type SupportTicketType = 'issue' | 'feedback';

export type SupportTicketMetadata = {
  posthogSessionId?: string;
  posthogDistinctId?: string;
  appVersion?: string;
  appEnvironment?: string;
  pageUrl?: string;
  userAgent?: string;
  submittedAt?: string;
};

export type SupportTicketInput = {
  type: SupportTicketType;
  message: string;
  metadata?: SupportTicketMetadata;
  contactEmail?: string;
};

export type SupportTicketSubmissionResult = {
  ticketId: string;
  providerMessageId?: string;
};

export type SupportTicketDeliveryService = {
  submitTicket: (
    input: SupportTicketInput,
  ) => Promise<SupportTicketSubmissionResult>;
};

type SupportTicketServiceOptions = {
  fetchFn?: typeof fetch;
};

export class SupportTicketService implements SupportTicketDeliveryService {
  private readonly fetchFn: typeof fetch;

  constructor(options: SupportTicketServiceOptions = {}) {
    this.fetchFn = options.fetchFn ?? fetch;
  }

  async submitTicket(
    input: SupportTicketInput,
  ): Promise<SupportTicketSubmissionResult> {
    const ticketId = randomUUID();

    const response = await this.fetchFn(SUPPORT_TICKET_WEBHOOK_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ticketId,
        type: input.type,
        message: input.message,
        contactEmail: input.contactEmail,
        metadata: input.metadata,
      }),
    });

    if (!response.ok) {
      const responseText = await response.text();
      throw new Error(
        `Support ticket submission failed: ${response.status} ${responseText}`,
      );
    }

    const data: unknown = await response.json();
    const providerMessageId =
      typeof data === 'object' &&
      data !== null &&
      'providerMessageId' in data &&
      typeof (data as { providerMessageId?: unknown }).providerMessageId ===
        'string'
        ? (data as { providerMessageId: string }).providerMessageId
        : undefined;

    log.info(
      `Submitted support ticket ${ticketId}${providerMessageId ? ` (provider id: ${providerMessageId})` : ''}`,
    );

    return { ticketId, providerMessageId };
  }
}
